function Obj2000033_Always(...)
w_CurrentInterractionObject =  GetGlobalVar("lottery_box_activated_by_Batman");
--print(w_CurrentInterractionObject);

if w_LotteryPhase == 1 then

    if w_LotteryGroupOrder == 1 then
        w_Group1SpawnPoints = {GetWaypointsInGroup(2000008)};
    elseif w_LotteryGroupOrder == 2 then
        w_Group1SpawnPoints = {GetWaypointsInGroup(2000011)};
    elseif w_LotteryGroupOrder == 3 then
