    elseif w_LotteryGroupOrder == 9 then
        w_Group1SpawnPoints = {GetWaypointsInGroup(2000020)};
    elseif w_LotteryGroupOrder == 10 then
        w_Group1SpawnPoints = {GetWaypointsInGroup(2000021)}; 
    end;

    ---spawn and insert in array

    for w_i = 1, #w_Group1SpawnPoints do
            table.insert(w_LotteryObjectsID,w_i, SpawnObject("LotteryBox",w_Group1SpawnPoints[w_i]))
    end;
    --print("LOOTERRRY ONLINE");
    w_LotteryPhase = 2;

elseif w_LotteryPhase == 2 then

    -- check for interaction and remove object from array

    for w_i2 = 1, #w_LotteryObjectsID do
        if w_CurrentInterractionObject == w_LotteryObjectsID[w_i2] and w_CurrentInterractionObject ~= -999 then
            HideObject(w_CurrentInterractionObject);
            Disable(w_CurrentInterractionObject);
            fz_tableRemove(w_LotteryObjectsID, w_LotteryObjectsID[w_i2])
        end;
    end;

    -- check for number of boxes remaining in the array

    if #w_LotteryObjectsID == 6 then
        w_LotteryPhase = 3;
    end

elseif w_LotteryPhase == 3 then

    for w_i3 = 1, #w_LotteryObjectsID do
        HideObject(w_LotteryObjectsID[w_i3]);
        Disable(w_LotteryObjectsID[w_i3]);
    end;


        w_LotteryObjectsID = {};
        w_Group1SpawnPoints = {}


    if w_LotteryGroupOrder < 5 then
        w_LotteryGroupOrder = w_LotteryGroupOrder + 1;
    else
        w_LotteryGroupOrder = 1;
    end;




        w_LotteryPhase = 1;

end


