function Obj95069_Always(...)
Wait(1000)

if GetGlobalVar("g_start_combat_music") > 0 then

    if GetGlobalVar("g_current_combat_music_id") < 0 or IsSoundIdPlaying(GetGlobalVar("g_current_combat_music_id")) == false then        
        local g_current_combat_music_id = StartCombatMusic();
        SetGlobalVar("g_current_combat_music_id", g_current_combat_music_id);
    end

elseif GetGlobalVar("g_current_combat_music_id") > 0 then --combat music should be stopped!    

    StopCombatMusic(GetGlobalVar("g_current_combat_music_id"));
    SetGlobalVar("g_current_combat_music_id", -1);

end


if GetGlobalVar("g_start_combat_music") > 0 and IsPlayerOnTheBatOrBatpod() == false then

    StopCombatMusic(GetGlobalVar("g_current_combat_music_id"));
    SetGlobalVar("g_current_combat_music_id", -1);
    SetGlobalVar("g_start_combat_music", 0)

end 


end

